contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(
        uint256 reqAmount,
        uint256 reqInterest,
        uint256 reqLtc,
        uint256 reqDuration
    ) public {
        require(reqAmount > 0 && reqLtc > 0 && reqDuration > 0);

        uint256 reqID = c.requestLoan(reqAmount, reqInterest, reqLtc, reqDuration); if (__ESBMC_reverted()) return;
        uint256 loanID = c.clearRequest(reqID, false, false); if (__ESBMC_reverted()) return;

        bool beforeActive = c.isActive(reqID); if (__ESBMC_reverted()) return;
        bool expired = c.isDefaulted(loanID); if (__ESBMC_reverted()) return;

        bool reverted;
        c.rollLoan(loanID); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted == (!beforeActive || expired));
    }
}

